};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_select_onclick
 * @description 조회 버튼 — 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_select_onclick = function (e) {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.btn_select_onclick" });
    }
};

/**
 * @method
 * @name btn_excel_onclick
 * @description 엑셀다운로드 — 「엑셀다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_excel_onclick = async function (e) {
    try {
        const today = $c.date.getServerDateTime("yyyyMMddHHmmss");
        const options = {
            fileName: "ULDSTF41610_파이프라인 진행 경과_" + today,
            sheetName: "파이프라인 진행 경과",
        };
        $c.data.downloadGridViewExcel(grd_grid, options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41610.btn_excel_onclick" });
    }
};

/**
 * @method
 * @name grd_grid_oncelldblclick
 * @description 목록 더블클릭
 * @param {Number} row 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} colid 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_grid_oncelldblclick = async function (row, columnIndex, colid) {
    try {
        if (row >= 0) {
            // 그리드에서 선택시
            await scwin.setBzProcsNo(row);
        }
        if ("34" === scwin.clickListProcsStatCd) {
            // 수정요청 리스트 팝업창
            let url = "/ui/lst/lstmgt/ULDSTF41611.xml";
            let popTitle = "기술성장기업 상장이후 성과분석 수정요청 리스트";
            let data = {
                // vBzProcsNo: scwin.vBzProcsNo,
                vBzProcsNo: dlt_selectList.getCellData(row, "follwBzProcsNo"),
                // pipeBzProcsNo: scwin.clickBzProcsNo,
            };
            const opts = {
                id: "ULDSTF41611",
                popupName: popTitle,
                width: 980,
                height: 400,
                frameModal: "top",
                type: "pageFramePopup",
            };
            await $c.win.openPopup(url, opts, data);
            scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41610.grd_grid_oncelldblclick" });
    }
};

