/**
 * @method
 * @name btn_comNm_onclick
 * @description 회사코드 버튼
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_comNm_onclick = function (e) {
    try {
        $c.cm.isurcdSearch(acb_isurCd, tbx_comNm);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.btn_comNm_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description MxDataSet_com_isur 필터 조건 판정(레거시 Gauce)
 * @param {Number} row 행 인덱스
 * @returns {Boolean} 판정 결과
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function (row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd_com_isur 키 입력 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function (kcode) {
    try {
        if (kcode === '13') {
            $c.cm.comConfirmSet();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 — 선택 행 처리
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function (row, colid) {
    try {
        $c.cm.comConfirmSet();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function (row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd_com_isur 포커스 진입 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function () {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 — 입력값 검증·포맷
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function () {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name btn_acpt_onclick
 * @description 접수 버튼 — 「접수」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_acpt_onclick = function (e) {
    try {
        scwin.receive("33");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.btn_acpt_onclick" });
    }
};

/**
 * @method
 * @name btn_ret_onclick
 * @description 반려 버튼 — 「반려」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_ret_onclick = function (e) {
    try {
        scwin.receive("37");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.btn_ret_onclick" });
    }
};

/**
 * @method
 * @name sbx_periodTp_onviewchange
 * @description 기간선택 selectBox 일자 세팅
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbx_periodTp_onviewchange = function (info) {
    try {
        let vTp = sbx_periodTp.getValue();
        $c.stf.setFromToDate(vTp, cal_sDate, cal_eDate);
        // 날짜 포맷 검증 추가
        $c.date.compareFromToDate(cal_sDate, cal_eDate, ["상장일 시작일자", "상장일 종료일자"], "yyyyMMdd");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.sbx_periodTp_onviewchange" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function (e) {
    try {
        popUpCalendar2(cal_eDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function (e) {
    try {
        popUpCalendar2(cal_sDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name grd_grid_oncellclick
 * @description 목록 더블클릭
 * @param {Number} row 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} colid 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_grid_oncellclick = async function (row, columnIndex, colid) {
    try {
        // 처리상태 제출완료 인 경우 접수, 반려 버튼 활성
        if (row >= 0) {
            // 그리드에서 선택시
            await scwin.setBzProcsNo(row);
        }
        if ("32" === scwin.clickListProcsStatCd) {
            // 접수,반려 버튼 활성화
            btn_acpt.show();
            btn_ret.show();

        } else {
            scwin.setRcvRetButtonFalse(); // 접수,반려 버튼 안보이게
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41610.grd_grid_oncellclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 목록을 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function () {

    if (cal_sDate.getValue() === "") {
        $c.win.alert($c.data.getMessage("com_crud_0199", "상장일 시작일자"));
        return;
    } else if (cal_eDate.getValue() === "") {
        $c.win.alert($c.data.getMessage("com_crud_0199", "상장일 종료일자"));
        return;
    } else {
        const sbmOptions = {
            id: "sbm_selectList",
            action: "/api/listing/lstmgt/pipelineprog/select-list",
            method: "get",
            ref: "dma_selectListReq",
            target: "dlt_selectList=body",
            isProcessMsg: false
        };
        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        await scwin.sbm_selectList_submitdone(sbmRtn);
    }
};

/**
 * @method
 * @name sbm_selectList_submitdone
 * @description sbm_selectList 통신 응답 후처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbm_selectList_submitdone = function (e) {
    if (dlt_selectList.getRowCount() <= 0) {
        dlt_selectList.setJSON([]);
    }
    scwin.setRcvRetButtonFalse(); // 접수,반려 버튼 안보이게

    // grd_grid.mergeCells(["pipelineNm", "clncindContn"]);
};

/**
 * @method
 * @name receive
 * @description 접수 처리를 실행한다.
 * @param {String} type 구분 값
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.receive = async function (type) {

    if (type === "33") scwin.typeString = "접수";
    else scwin.typeString = "반려";

    let vAnswer = await $c.win.confirm("선택된 항목을 모두 " + scwin.typeString + "처리 하시겠습니까?");
    if (vAnswer) {
        dma_processPipelineprog.set("listProcsStatCd", type); // 상장처리상태코드
        dma_processPipelineprog.set("listBzTpCd", "800"); // 상장업무구분코드
        dma_processPipelineprog.set("pipeBzProcsNo", scwin.clickBzProcsNo); // 파이프라인 업무처리번호
        dma_processPipelineprog.set("pipeIsurCd", scwin.clickIsurCd); // 발행기관코드

        const sbmOptions = {
            id: "sbm_processPipelineprog",
            action: "/api/listing/lstmgt/pipelineprog/process-pipelineprog",
            method: "post",
            ref: "dma_processPipelineprog",
            // target : "dlt_processPipelineprog=body",
            isProcessMsg: false
        };
        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        await scwin.sbm_processPipelineprog_submitdone(sbmRtn);
    }
};

/**
 * @method
 * @name sbm_processPipelineprog_submitdone
 * @description sbm_processPipelineprog 통신 응답 후처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbm_processPipelineprog_submitdone = function (e) {
    // scwin.alertJobMsg('S1');
    $c.win.alert($c.data.getMessage("com_complete_0150", scwin.typeString));
    scwin.listSync();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name init
 * @description 화면 초기화 — 조회조건·상태값 기본 설정.
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    $c.win.setEnterKeyEvent(grp_search, scwin.btn_select_onclick);
    $c.cm.searchIsurCode(acb_isurCd, tbx_comNm);
    scwin.setCode();
    scwin.setRcvRetButtonFalse(); // 접수,반려 버튼 안보이게
    scwin.listSync();
}

/**
 * @method
 * @name setCode
 * @description 코드 값을 화면에 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function () {
    //  기간 from~ to  셋팅
    let vCurDate = $c.date.getServerDateTime();
    cal_sDate.setValue($c.date.addDate(vCurDate, -365)); // 일년 날짜
    cal_eDate.setValue(vCurDate); // 현재날짜

    $c.stf.comboCbDataSetPeriod(sbx_periodTp);
};

/**
 * @method
 * @name setRcvRetButtonFalse
 * @description 접수·반려 버튼을 비활성화한다.
 * @returns {void}
 * @hidden N
 */
scwin.setRcvRetButtonFalse = function () {
    btn_acpt.hide();
    btn_ret.hide();
};

